            1: (len_enc, DataEncoding.ENCODING_INTEGER),  # 1 byte int [8 bit]
            2: (len_enc, DataEncoding.ENCODING_INTEGER),  # 2 byte int [16 bit] or date...
            3: (len_enc, DataEncoding.ENCODING_INTEGER),  # 3 byte int [24 bit]
            4: (len_enc, DataEncoding.ENCODING_INTEGER),  # 4 byte int [32 bit] or date...
            5: (len_enc, DataEncoding.ENCODING_REAL),  # 4 byte float [32 bit]
            6: (len_enc, DataEncoding.ENCODING_INTEGER),  # 6 byte int [48 bit]
            7: (len_enc, DataEncoding.ENCODING_INTEGER),  # 8 byte int [64 bit]
            8: (0, DataEncoding.ENCODING_NULL),  # Nothing...
            9: (len_enc - 8, DataEncoding.ENCODING_BCD),  # 2 digit BCD [8 bit]
            10: (len_enc - 8, DataEncoding.ENCODING_BCD),  # 4 digit BCD [16 bit]
            11: (len_enc - 8, DataEncoding.ENCODING_BCD),  # 6 digit BCD [24 bit]
            12: (len_enc - 7, DataEncoding.ENCODING_BCD),  # 8 digit BCD [32 bit]
            13: (len_enc, DataEncoding.ENCODING_VARIABLE_LENGTH),  # variable length
            14: (len_enc, DataEncoding.ENCODING_BCD),  # 12 digit BCD [40 bit]
            15: (0, DataEncoding.ENCODING_NULL)  # Special Function FIXME
        }.get(len_enc, (len_enc, None))

    def get_records(self):
        records = []
        for i in range(0, len(self.parts), 2):
            dif = self.parts[i]
            if dif == self.MORE_RECORDS_FOLLOW:
                break
            elif dif == 0x0F:
                records.append(None)
            else:
                func = self.function_type
                unit = self.get_unit(i)
                value = self.get_value(i)
                parsed_value = self.get_parsed_value(i)
                records.append({
                    'function': func,
                    'unit': unit,
                    'value': value,
                    'parsed_value': parsed_value,
                })
        return records

    def get_unit(self, index):
        # Implement the logic to get the unit
        if index == 1:
            return "seconds"
        # Add more conditions as needed
        return 'none'

    def get_value(self, index):
        # Implement the logic to get the value
        return self.get_record_value(index)

    def get_parsed_value(self, index):
        # Implement the logic to get the parsed value
        return self.get_record_value(index)

    def get_record_value(self, index):
        # Implement the logic to get the record value
        if index == 5:
            real_data = self.parts[index*2+1:index*2+5]
            return struct.unpack('f', bytes(real_data))[0]
        elif index == 9:
            real_data = self.parts[index*2+1:index*2+9]
            return struct.unpack('q', bytes(real_data))[0]
        # Add more conditions as needed
        return 0

    def to_JSON(self):
        data = {
            'function': self.function_type,
            'unit': self.get_unit(0),
            'value': self.get_value(0),
            'parsed_value': self.get_parsed_value(0)
        }
        return json.dumps(data)
